{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "gap",
      "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
      "description": "Spacing step (number literal): 0, 0.5, 1, 1.5, 2, 3, 4, 5, 6, 8, 10. Pass as a JSX number expression e.g. gap={4}, NOT a string like gap=\"4\"."
    },
    {
      "name": "padding",
      "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
      "description": "Inner padding on all sides, using the spacing scale (0, 0.5, 1, 1.5, 2, 3, 4, 5, 6, 8, 10). Matches the padding prop on Card, LayoutContent, and LayoutPanel. Pass as a JSX number expression e.g. padding={3}."
    },
    {
      "name": "paddingInline",
      "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
      "description": "Inline (horizontal) padding, using the spacing scale. Overrides padding on the inline axis when both are set."
    },
    {
      "name": "paddingInlineStart",
      "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
      "description": "Inline-start padding, using the spacing scale (left in LTR, right in RTL). Overrides paddingInline and padding on that edge only."
    },
    {
      "name": "paddingInlineEnd",
      "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
      "description": "Inline-end padding, using the spacing scale (right in LTR, left in RTL). Overrides paddingInline and padding on that edge only."
    },
    {
      "name": "paddingBlock",
      "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
      "description": "Block (vertical) padding, using the spacing scale. Overrides padding on the block axis when both are set."
    },
    {
      "name": "paddingBlockStart",
      "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
      "description": "Block-start (top) padding, using the spacing scale. Overrides paddingBlock and padding on that edge only."
    },
    {
      "name": "paddingBlockEnd",
      "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
      "description": "Block-end (bottom) padding, using the spacing scale. Overrides paddingBlock and padding on that edge only."
    },
    {
      "name": "isScrollable",
      "type": "boolean",
      "description": "Enables scrollable overflow (overflow: auto). Matches isScrollable on LayoutContent and LayoutPanel.",
      "default": "false"
    },
    {
      "name": "width",
      "type": "SizeValue",
      "description": "Width of the stack container. Numbers are treated as pixels, strings are used as-is (e.g., '100%')."
    },
    {
      "name": "height",
      "type": "SizeValue",
      "description": "Height of the stack container. Numbers are treated as pixels, strings are used as-is (e.g., '100%')."
    },
    {
      "name": "maxWidth",
      "type": "SizeValue",
      "description": "Maximum width of the stack container. Numbers are treated as pixels, strings are used as-is (e.g., '100%')."
    },
    {
      "name": "minHeight",
      "type": "SizeValue",
      "description": "Minimum height of the stack container. Numbers are treated as pixels, strings are used as-is (e.g., '100%')."
    },
    {
      "name": "hAlign",
      "type": "'start' | 'center' | 'end' | 'between' | 'around' | 'evenly'",
      "description": "Horizontal (main-axis) alignment of items."
    },
    {
      "name": "vAlign",
      "type": "'start' | 'center' | 'end' | 'stretch'",
      "description": "Vertical (cross-axis) alignment of items.",
      "default": "'stretch'"
    },
    {
      "name": "justify",
      "type": "'start' | 'center' | 'end' | 'between' | 'around' | 'evenly'",
      "description": "Main-axis alignment alias for hAlign. Mirrors CSS justify-content. When hAlign is also set, hAlign wins."
    },
    {
      "name": "align",
      "type": "'start' | 'center' | 'end' | 'stretch'",
      "description": "Cross-axis alignment alias for vAlign. Mirrors CSS align-items. When vAlign is also set, vAlign wins."
    },
    {
      "name": "wrap",
      "type": "'nowrap' | 'wrap' | 'wrap-reverse'",
      "description": "Flex wrap behavior.",
      "default": "'nowrap'"
    },
    {
      "name": "as",
      "type": "ElementType",
      "description": "HTML element to render as the stack container.",
      "default": "'div'"
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "Stack content."
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value, not an inline style object like style={{}}."
    },
    {
      "name": "className",
      "type": "string",
      "description": "Class name added to the stack element, after the component styles."
    },
    {
      "name": "style",
      "type": "CSSProperties",
      "description": "Inline styles for the stack element. width, height, maxWidth, and minHeight win over the same properties here."
    },
    {
      "name": "ref",
      "type": "Ref<HTMLElement>",
      "description": "Ref to the rendered stack element."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
